1810	\begin{theorem}
1811	[Riemann--Roch]
1812	  \label{thm:adelic_riemannRoch}
1813	  \lean{AlgebraicGeometry.Adelic.riemannRoch}
1814	  \uses{thm:adelic_chi_eq_chi_zero_add_degree, thm:adelic_serreDuality}
1815	  % [papaioannou] Thm. 1.27 (dim D = deg D + 1 - g + dim(W - D)); [cff] Thm. 14.1; [vater] Thm. 1.55
1816	  \source{papaioannou-algebraic-rr, cff-curves-function-fields, vater-weil-differentials}
1817	  For every Weil divisor \(D\) and canonical divisor \(K_C\),
1818	  \[
1819	    \ell(D) - \ell(K_C - D) \;=\; \deg D + 1 - g .
1820	  \]
1821	\end{theorem}
1822	\begin{proof}
1823	  Immediate from the two keystones: the \(\chi\)-ledger
1824	  \Cref{thm:adelic_chi_eq_chi_zero_add_degree} gives
1825	  \(\ell(D) - i(D) = \deg D + 1 - g\), and Serre duality
1826	  \Cref{thm:adelic_serreDuality} gives \(i(D) = \ell(K_C - D)\);
1827	  substituting the second into the first yields the identity.
1828	\end{proof}

