332	\begin{lemma}
333	  [Birationality of the canonical map]
334	  \label{lem:symmetric_product_to_jacobian}
335	  \source{abelian-varieties:page-0107, abelian-varieties:page-0108,
336	    abelian-varieties:page-0109}
337	  \uses{def:symmetric_product_to_jacobian_morphism}
338	
339	  For \(1\le r\le g\), the morphism
340	  \[
341	    f^{(r)}\colon C^{(r)}\longrightarrow W^r
342	  \]
343	  is birational.  In particular, \(W^g=J\), and
344	  \(f^{(g)}\colon C^{(g)}\to J\) is a birational surjective morphism.
345	\end{lemma}
346	
347	\begin{proof}
348	  \uses{lem:symmetric_product_general_divisor,
349	    lem:symmetric_product_tangent_exact, lem:jacobian_dimension}
350	  The product \(C^r\) has dimension \(r\), and the finite surjective map
351	  \(C^r\to C^{(r)}\) shows that \(C^{(r)}\) also has dimension \(r\).
352	  By \cref{lem:symmetric_product_general_divisor}, the map is injective on
353	  geometric points over a dense open subset.  It is therefore generically
354	  quasi-finite, so its image \(W^r\) has dimension \(r\).  Thus the induced extension
355	  of function fields has separable degree one.  In positive characteristic
356	  this still leaves open the possibility of a nontrivial purely
357	  inseparable extension.  Choose \(D\) in that open.  Then \(h^0(D)=1\),
358	  so \cref{lem:symmetric_product_tangent_exact} makes
359	  \(d f^{(r)}_D\) injective.  Since source and image both have dimension
360	  \(r\), the differential has full rank, and the function-field extension
361	  is generically separable.  Its inseparable degree is therefore also one.
362	  The function fields of \(C^{(r)}\) and \(W^r\) are equal, proving
363	  birationality.
364	
365	  For \(r=g\), the image \(W^g\) is a closed irreducible subvariety of the
366	  irreducible variety \(J\) and has dimension \(g=\dim J\), the latter
367	  equality being \cref{lem:jacobian_dimension}.  Hence
368	  \(W^g=J\).  Surjectivity follows because \(C^{(g)}\) is proper and its
369	  image is exactly \(W^g\).
370	\end{proof}
