372	\section{Descent and the universal property}
373	\label{sec:albaneseup_descent}
374	
375	\begin{lemma}
376	  [Descent through the birational symmetric power]
377	  \label{lem:descent_through_birational_sigma}
378	  \source{abelian-varieties:page-0110}
379	  \lean{AlgebraicGeometry.Pic0.descentThroughBirationalSigma}
380	  \uses{def:symmetric_product_av_map,
381	    def:symmetric_product_to_jacobian_morphism}
382	
383	  Let \(A\) be an abelian variety and let
384	  \(\varphi\colon C\to A\) be pointed at \(P_0\).  There is a unique
385	  regular morphism \(\psi\colon J\to A\) such that
386	  \[
387	    \varphi^{(g)}=\psi\circ f^{(g)}.
388	  \]
389	\end{lemma}
390	
391	\begin{proof}
392	  \uses{lem:symmetric_product_av_map, lem:symmetric_product_to_jacobian,
393	    lem:symmetric_power_nonsingular, thm:rational_map_to_av_extends}
394	  On dense opens \(U\subseteq C^{(g)}\) and \(V\subseteq J\), the map
395	  \(f^{(g)}|_U\colon U\to V\) is an isomorphism.  Thus
396	  \(\varphi^{(g)}|_U\circ(f^{(g)}|_U)^{-1}\) defines a rational map
397	  \(J\dashrightarrow A\).  The Jacobian is smooth and \(A\) is an abelian
398	  variety, so \cref{thm:rational_map_to_av_extends} extends this rational
399	  map uniquely to a regular morphism \(\psi\colon J\to A\).  The two
400	  morphisms \(\varphi^{(g)}\) and \(\psi\circ f^{(g)}\) agree on the dense
401	  open \(U\); since \(C^{(g)}\) is nonsingular by
402	  \cref{lem:symmetric_power_nonsingular}, hence reduced, and \(A\) is separated, they
403	  agree everywhere.  The same dense-open agreement proves uniqueness.
404	\end{proof}
405	
406	\begin{definition}
407	  [The basepoint section of the symmetric power]
408	  \label{def:basepoint_section_symmetric_power}
409	  \uses{def:symmetric_power_curve}
410	
411	  Define
412	  \[
413	    s_{P_0}\colon C\longrightarrow C^{(g)},\qquad
414	    Q\longmapsto Q+(g-1)P_0.
415	  \]
416	\end{definition}
417	
418	\begin{lemma}
419	  [The basepoint section followed by the canonical map]
420	  \label{lem:basepoint_section_to_jacobian}
421	  \source{abelian-varieties:page-0110}
422	  \uses{def:basepoint_section_symmetric_power,
423	    def:symmetric_product_to_jacobian_morphism,
424	    def:abel_jacobi_morphism}
425	
426	  One has \(f^{(g)}\circ s_{P_0}=\iota_{P_0}\).
427	\end{lemma}
428	
429	\begin{proof}
430	  At \(Q\in C\), the left side represents
431	  \[
432	    \mathcal O_C(Q+(g-1)P_0-gP_0)=\mathcal O_C(Q-P_0),
433	  \]
434	  which is the defining class of \(\iota_{P_0}(Q)\).
435	\end{proof}
436	
437	\begin{lemma}
438	  [The basepoint section followed by a symmetric sum]
439	  \label{lem:basepoint_section_symmetric_map}
440	  \source{abelian-varieties:page-0110}
441	  \uses{def:basepoint_section_symmetric_power,
442	    def:symmetric_product_av_map}
443	
444	  If \(\varphi(P_0)=0_A\), then
445	  \(\varphi^{(g)}\circ s_{P_0}=\varphi\).
446	\end{lemma}
447	
448	\begin{proof}
449	  At \(Q\in C\), the left side is
450	  \(\varphi(Q)+(g-1)\varphi(P_0)=\varphi(Q)\).
451	\end{proof}
452	
453	\begin{lemma}
454	  [Equivalence of the two factorisation equations]
455	  \label{lem:albanese_eq_iff_symmetricPower_eq}
456	  \source{abelian-varieties:page-0110}
457	  \lean{AlgebraicGeometry.Pic0.albanese_eq_iff_symmetricPower_eq}
458	  \uses{def:abel_jacobi_morphism, def:symmetric_product_av_map,
459	    def:symmetric_product_to_jacobian_morphism}
460	
461	  Let \(\varphi\colon C\to A\) satisfy \(\varphi(P_0)=0_A\).  For every
462	  regular morphism \(\psi\colon J\to A\),
463	  \[
464	    \varphi=\psi\circ\iota_{P_0}
465	      \quad\Longleftrightarrow\quad
466	    \varphi^{(g)}=\psi\circ f^{(g)}.
467	  \]
468	\end{lemma}
469	
470	\begin{proof}
471	  \uses{lem:abel_jacobi_morphism, lem:symmetric_product_av_map,
472	    lem:av_regular_map_is_hom, lem:basepoint_section_to_jacobian,
473	    lem:basepoint_section_symmetric_map}
474	  Suppose first that \(\varphi=\psi\circ\iota_{P_0}\).  Evaluating at
475	  \(P_0\) gives \(\psi(0_J)=0_A\), so
476	  \cref{lem:av_regular_map_is_hom} shows that \(\psi\) is a homomorphism.
477	  Pulling both sides of the desired symmetric-power equation back to
478	  \(C^g\), both send \((P_1,\ldots,P_g)\) to
479	  \(\sum_i\psi(\iota_{P_0}(P_i))\).  The uniqueness clause in the
480	  universal property of \(C^{(g)}\) gives the equation on \(C^{(g)}\).
481	
482	  Conversely, compose the symmetric-power equation with
483	  \(s_{P_0}\).  The two basepoint-section identities
484	  \cref{lem:basepoint_section_symmetric_map} and
485	  \cref{lem:basepoint_section_to_jacobian} identify the resulting equation with
486	  \(\varphi=\psi\circ\iota_{P_0}\).  Hence
487	  \(\varphi=\psi\circ\iota_{P_0}\).
488	\end{proof}
489	
490	\begin{theorem}
491	  [Albanese factorisation through \(\Pic^0_{C/k}\)]
492	  \label{thm:albanese_universal_property}
493	  \source{abelian-varieties:page-0110}
494	  \lean{AlgebraicGeometry.Pic0.albanese_universal_property}
495	  \uses{def:abel_jacobi_morphism}
496	
497	  For every abelian variety \(A\) and every morphism
498	  \(\varphi\colon C\to A\) with \(\varphi(P_0)=0_A\), there exists a unique
499	  regular morphism \(\psi\colon J\to A\) such that
500	  \[
501	    \varphi=\psi\circ\iota_{P_0}.
502	  \]
503	\end{theorem}
504	
505	\begin{proof}
506	  \uses{lem:descent_through_birational_sigma,
507	    lem:albanese_eq_iff_symmetricPower_eq}
508	  By \cref{lem:descent_through_birational_sigma}, there is a unique
509	  \(\psi\colon J\to A\) satisfying
510	  \(\varphi^{(g)}=\psi\circ f^{(g)}\).  The equivalence in
511	  \cref{lem:albanese_eq_iff_symmetricPower_eq}, applied to every candidate
512	  morphism, transports both existence and uniqueness to the equation
513	  \(\varphi=\psi\circ\iota_{P_0}\).
514	\end{proof}
515	
516	\begin{corollary}
517	  [Albanese universal property]
518	  \label{cor:albanese_universal_property_homomorphism}
519	  \source{abelian-varieties:page-0110}
520	  \uses{thm:albanese_universal_property, lem:av_regular_map_is_hom,
521	    lem:abel_jacobi_morphism}
522	
523	  In the situation of \cref{thm:albanese_universal_property}, the unique
524	  factor \(\psi\colon J\to A\) is a homomorphism of group schemes.
525	  Consequently \(\iota_{P_0}\) is initial among pointed morphisms from
526	  \(C\) to abelian varieties.
527	\end{corollary}
528	
529	\begin{proof}
530	  Since \(\iota_{P_0}(P_0)=0_J\) and \(\varphi(P_0)=0_A\), the
531	  factorisation gives \(\psi(0_J)=0_A\).  The pointed rigidity theorem
532	  \cref{lem:av_regular_map_is_hom} therefore makes \(\psi\) a group
533	  homomorphism.  Uniqueness among all regular factors implies uniqueness
534	  among homomorphisms.
535	\end{proof}

 70	\section{Symmetric powers and their canonical maps}
 71	\label{sec:albaneseup_symmetric_powers}
 72	
 73	\begin{definition}
 74	  [Symmetric power of a curve]
 75	  \label{def:symmetric_power_curve}
 76	  \source{abelian-varieties:page-0100}
 77	
 78	  For \(r\ge 1\), the \emph{\(r\)-th symmetric power} \(C^{(r)}\) is the
 79	  quotient of \(C^r\) by permutation of the factors.  It is equipped with a
 80	  finite surjective morphism \(\pi_r\colon C^r\to C^{(r)}\).  Every
 81	  symmetric morphism from \(C^r\) to a \(k\)-scheme factors uniquely through
 82	  \(\pi_r\).
 83	\end{definition}
 84	
 85	\begin{definition}
 86	  [The symmetric-power carrier]
 87	  \label{def:symmetric_power_curve_carrier}
 88	  \lean{AlgebraicGeometry.Pic0.SymmetricPower}
 89	  \uses{def:symmetric_power_curve}
 90	
 91	  The underlying \(k\)-scheme of \(C^{(r)}\) is denoted
 92	  \(\operatorname{SymmetricPower}(C,r)\).
 93	\end{definition}
 94	
 95	\begin{lemma}
 96	  [Nonsingularity of a symmetric power of a curve]
 97	  \label{lem:symmetric_power_nonsingular}
 98	  \source{abelian-varieties:page-0100}
 99	  \uses{def:symmetric_power_curve}
100	
101	  If \(C\) is nonsingular, then \(C^{(r)}\) is nonsingular.
102	\end{lemma}
103	
104	\begin{proof}
105	  At the image of \((Q,\ldots,Q)\), choose a parameter \(X\) at \(Q\).
106	  The completed local ring of \(C^r\) is
107	  \(k[[X_1,\ldots,X_r]]\), and the completed local ring of the quotient is
108	  its invariant subring.  The fundamental theorem on symmetric functions
109	  identifies this with
110	  \(k[[\sigma_1,\ldots,\sigma_r]]\), which is regular.  At a divisor with
111	  several distinct support points, the completed local ring is the
112	  completed tensor product of the corresponding invariant power-series
113	  rings, and is again regular.
114	\end{proof}
115	
116	\begin{definition}
117	  [The symmetric sum morphism]
118	  \label{def:symmetric_product_av_map}
119	  \lean{AlgebraicGeometry.Pic0.symmetricPowerAVMap}
120	  \uses{def:symmetric_power_curve_carrier}
121	
122	  For a morphism \(\varphi\colon C\to A\) to an abelian variety, denote the
123	  induced morphism from the symmetric-power carrier by
124	  \(\varphi^{(r)}\colon C^{(r)}\to A\).
125	\end{definition}
126	
127	\begin{lemma}
128	  [Symmetrisation of a morphism to an abelian variety]
129	  \label{lem:symmetric_product_av_map}
130	  \source{abelian-varieties:page-0110}
131	  \uses{def:symmetric_power_curve, def:symmetric_product_av_map}
132	
133	  Let \(A\) be an abelian variety and let \(\varphi\colon C\to A\) be a
134	  morphism.  There is a unique morphism
135	  \(\varphi^{(r)}\colon C^{(r)}\to A\) satisfying
136	  \[
137	    \varphi^{(r)}(P_1+\cdots+P_r)
138	      =\varphi(P_1)+\cdots+\varphi(P_r).
139	  \]
140	\end{lemma}
141	
142	\begin{proof}
143	  The morphism \(C^r\to A\) obtained by applying \(\varphi\) in every
144	  coordinate and then adding is invariant under every permutation, because
145	  the group law of \(A\) is commutative.  The universal property of
146	  \(C^{(r)}\) gives the unique factorisation.
147	\end{proof}
148	
149	\begin{definition}
150	  [The canonical symmetric-power morphism to the Jacobian]
151	  \label{def:symmetric_product_to_jacobian_morphism}
152	  \source{abelian-varieties:page-0107}
153	  \lean{AlgebraicGeometry.Pic0.symmetricPowerToJacobian}
154	  \uses{def:abel_jacobi_morphism, def:symmetric_product_av_map}
155	
156	  Symmetrising \(\iota_{P_0}\) gives the canonical morphism
157	  \[
158	    f^{(r)}\colon C^{(r)}\longrightarrow J,
159	    \qquad
160	    D\longmapsto[\mathcal O_C(D-rP_0)].
161	  \]
162	  Its image is denoted \(W^r\).  The fibre through an effective divisor
163	  \(D\) is its complete linear system \(|D|\).
164	\end{definition}
